CREATE TABLE "demo_sample" ( "id" varchar(36) NOT NULL PRIMARY KEY, "created_by" varchar(36) NOT NULL, "created_at" bigint NOT NULL, "updated_at" bigint NOT NULL, "row_version" bigint NOT NULL, "code" varchar(32) NOT NULL, "title" varchar(120) NOT NULL, "note" text NOT NULL, "stage" varchar(16) NOT NULL, "character_count" bigint, "attachment_id" varchar(36), CONSTRAINT "uq_demo_sample_owner_code" UNIQUE ("created_by", "code"), CONSTRAINT "uq_demo_sample_attachment" UNIQUE ("attachment_id"), CHECK ("row_version" >= 1), CHECK ("character_count" >= 0), CHECK ("stage" IN ('draft', 'ready')) );
CREATE INDEX "ix_demo_sample_owner_created" ON "demo_sample" ("created_by", "created_at", "id");
